css:
/* Pedido de 01/11: redistribuir apenas os blocos Instituto e Agenda da Home. */
[data-page="home"] #sobre-instituto-home > .line-title-wrapper,
[data-page="home"] #agenda-home > .line-title-wrapper,
[data-page="home"] #aproximacao-home > .line-title-wrapper {
  grid-column: 1 / span 2;
  min-width: 0;
}
[data-page="home"] #sobre-instituto-home > .description-wrapper,
[data-page="home"] #agenda-home > .description-wrapper,
[data-page="home"] #aproximacao-home > .description-wrapper {
  grid-column: 3 / -1;
  width: 100%;
  min-width: 0;
}
[data-page="home"] #sobre-instituto-home > .description-wrapper > .button-primary,
[data-page="home"] #aproximacao-home > .description-wrapper > .button-primary {
  align-self: flex-start;
}
